import { sql, type Kysely } from 'kysely';

/**
 * Better Auth tables, as generated by the Better Auth CLI (`npx auth generate --config
 * db/better-auth.config.ts`) for better-auth 1.7 with the API-key plugin; then our three
 * `user` fields typed and constrained (entities `User`; security design, "People are checked too").
 */
export async function up(db: Kysely<unknown>) {
  // --- generated by the Better Auth CLI ---
  await sql`
    create table "user" ("id" text not null primary key, "name" text not null, "email" text not null unique, "emailVerified" boolean not null, "image" text, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz default CURRENT_TIMESTAMP not null, "organisation_id" text, "role" text, "status" text);

    create table "session" ("id" text not null primary key, "expiresAt" timestamptz not null, "token" text not null unique, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz not null, "ipAddress" text, "userAgent" text, "userId" text not null references "user" ("id") on delete cascade);

    create table "account" ("id" text not null primary key, "accountId" text not null, "providerId" text not null, "userId" text not null references "user" ("id") on delete cascade, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamptz, "refreshTokenExpiresAt" timestamptz, "scope" text, "password" text, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz not null);

    create table "verification" ("id" text not null primary key, "identifier" text not null, "value" text not null, "expiresAt" timestamptz not null, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz default CURRENT_TIMESTAMP not null);

    create table "apikey" ("id" text not null primary key, "configId" text not null, "name" text, "start" text, "referenceId" text not null, "prefix" text, "key" text not null, "refillInterval" integer, "refillAmount" integer, "lastRefillAt" timestamptz, "enabled" boolean, "rateLimitEnabled" boolean, "rateLimitTimeWindow" integer, "rateLimitMax" integer, "requestCount" integer, "remaining" integer, "lastRequest" timestamptz, "expiresAt" timestamptz, "createdAt" timestamptz not null, "updatedAt" timestamptz not null, "permissions" text, "metadata" text);

    create index "session_userId_idx" on "session" ("userId");
    create index "account_userId_idx" on "account" ("userId");
    create index "verification_identifier_idx" on "verification" ("identifier");
    create index "apikey_configId_idx" on "apikey" ("configId");
    create index "apikey_referenceId_idx" on "apikey" ("referenceId");
    create index "apikey_key_idx" on "apikey" ("key");
  `.execute(db);

  // --- our additional user fields ---
  await sql`
    ALTER TABLE "user"
      ALTER COLUMN organisation_id TYPE uuid USING organisation_id::uuid,
      ALTER COLUMN organisation_id SET NOT NULL,
      ADD CONSTRAINT user_organisation_fk FOREIGN KEY (organisation_id) REFERENCES organisations (organisation_id),
      ALTER COLUMN role SET DEFAULT 'Contributor',
      ALTER COLUMN role SET NOT NULL,
      ADD CONSTRAINT user_role_check CHECK (role IN ('Reader', 'Contributor', 'Approver', 'Admin')),
      ALTER COLUMN status SET DEFAULT 'active',
      ALTER COLUMN status SET NOT NULL,
      ADD CONSTRAINT user_status_check CHECK (status IN ('active', 'deactivated')),
      ADD CONSTRAINT user_organisation_id_key UNIQUE (organisation_id, id),
      ADD CONSTRAINT user_organisation_email_key UNIQUE (organisation_id, email)
  `.execute(db);
}
